	@Test
	void constructCreatesTwoPerObjectReifiers() throws Exception {
		String query = "CONSTRUCT { ?s <urn:p> <urn:o1> ~<urn:r1>, <urn:o2> ~<urn:r2> } "
				+ "WHERE { VALUES ?s { <urn:s> } }";
		Model actual = new LinkedHashModel();
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection();
					GraphQueryResult result = connection.prepareGraphQuery(query).evaluate()) {
				while (result.hasNext()) {
					actual.add(result.next());
				}
			}
		} finally {
			repository.shutDown();
		}

		IRI subject = VALUE_FACTORY.createIRI("urn:s");
		IRI predicate = VALUE_FACTORY.createIRI("urn:p");
		IRI firstObject = VALUE_FACTORY.createIRI("urn:o1");
		IRI secondObject = VALUE_FACTORY.createIRI("urn:o2");
		assertThat(actual).containsExactlyInAnyOrder(
				VALUE_FACTORY.createStatement(subject, predicate, firstObject),
				VALUE_FACTORY.createStatement(subject, predicate, secondObject),
				VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:r1"), RDF.REIFIES,
						VALUE_FACTORY.createTripleTerm(subject, predicate, firstObject)),
				VALUE_FACTORY.createStatement(VALUE_FACTORY.createIRI("urn:r2"), RDF.REIFIES,
						VALUE_FACTORY.createTripleTerm(subject, predicate, secondObject)));
	}

