	@Test
	void duplicateValuesRowsAllocateFreshReifiersForEveryObject() throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.prepareUpdate("INSERT { ?s <urn:p> <urn:o1> ~[] {| <urn:row> ?row |}, "
						+ "<urn:o2> ~[] } WHERE { VALUES (?s ?row) { (<urn:s> 1) (<urn:s> 1) } }").execute();

				List<Statement> reifiers = reificationStatements(connection);
				assertThat(reifiers).hasSize(4);
				assertThat(reifiers.stream().map(Statement::getSubject).distinct().toList()).hasSize(4)
						.allSatisfy(subject -> assertThat(subject).isInstanceOf(BNode.class));
				assertThat(reifiers.stream().map(Statement::getObject).distinct().toList()).hasSize(2);
				assertThat(reifiers.stream()
						.filter(statement -> statement.getObject()
								.equals(
										VALUE_FACTORY.createTripleTerm(VALUE_FACTORY.createIRI("urn:s"),
												VALUE_FACTORY.createIRI("urn:p"), VALUE_FACTORY.createIRI("urn:o1"))))
						.count())
								.isEqualTo(2);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static List<Statement> reificationStatements(SailRepositoryConnection connection) throws Exception {
		List<Statement> statements = new ArrayList<>();
		try (var result = connection.getStatements(null, RDF.REIFIES, null, false)) {
			while (result.hasNext()) {
				statements.add(result.next());
			}
		}
		return statements;
	}
